"""Tests for Cadence .tarpt parser."""

import os
import pytest
from openroad_py.timing.tarpt_parser import TarptParser, TimingPath, TimingReportData

TARPT_PATH = r"C:\High-Speed-LLM-using-RAG\data\ActualLogFiles\route_reg2reg.tarpt"


def test_parser_synthetic_string():
    sample_text = """###############################################################
#  Generated by:      Cadence Innovus 23.16-e036_1
#  OS:                Linux x86_64
#  Design:            TestDesign
#  Command:           report_timing
###############################################################
Path 1: VIOLATED (-0.0500 ns) Setup Check with Pin reg1/D
View: test_view
Group: reg2reg
Startpoint: (R) reg0/CP
Clock: (R) clk1
Endpoint: (R) reg1/D
Clock: (R) clk1
Required Time:= 10.0000
Arrival:= 10.0500
Slack:= -0.0500
Timing Path:

#---------------------------------------------------------------------------------------------------------------------------------------
# Arrival Delay Edge Cell Timing Point
#---------------------------------------------------------------------------------------------------------------------------------------
   0.0000 - R (arrival) clk1
   0.0000 - R (net) clk1
   0.0000 0.0000 R DFF reg0/CP
   0.1000 0.1000 R DFF reg0/Q
   - - R (net) n_data0
   0.2000 0.1000 F INV u_inv/A
   0.2500 0.0500 R INV u_inv/Z
   - - R (net) n_data1
   0.3000 0.0500 R DFF reg1/D
"""
    parser = TarptParser()
    report = parser.parse_text(sample_text)
    assert len(report.paths) == 1
    p = report.paths[0]
    assert p.id == 1
    assert p.status == "VIOLATED"
    assert p.slack == -0.0500
    assert p.required_time == 10.0
    assert p.startpoint == "reg0/CP"
    assert p.endpoint == "reg1/D"
    assert p.launch_clock == "clk1"
    assert p.view == "test_view"
    assert p.group == "reg2reg"
    assert p.logic_level == 1  # 1 logic gate: u_inv
    assert "n_data0" in p.nets or "n_data1" in p.nets
    assert report.categories["all"].failing_path == 1
    assert report.categories["all"].total_path == 1
    assert report.categories["all"].tns == -0.0500


@pytest.mark.skipif(not os.path.exists(TARPT_PATH), reason="route_reg2reg.tarpt not found")
def test_parse_real_route_reg2reg():
    parser = TarptParser()
    report = parser.parse_file(TARPT_PATH)

    # File headers
    assert "Innovus" in report.generated_by
    assert report.design_name == "Ethernet_SS"

    # Paths count
    assert len(report.paths) == 200

    # Failing & Passing stats
    failing = [p for p in report.paths if p.slack < 0]
    passing = [p for p in report.paths if p.slack >= 0]
    assert len(failing) == 5
    assert len(passing) == 195

    # Categories
    assert "all" in report.categories
    assert "reg2reg" in report.categories
    cat = report.categories["reg2reg"]
    assert cat.total_path == 200
    assert cat.failing_path == 5
    assert cat.passing_path == 195
    assert cat.wns == -0.0087
    assert cat.tns == -0.0168

    # Path 1 check
    p1 = report.paths[0]
    assert p1.id == 1
    assert p1.slack == -0.0087
    assert p1.required_time == 21.8229
    assert "LOCKUP" in p1.startpoint
    assert "SNPS_PipeTail" in p1.endpoint
    assert p1.group == "reg2reg"
    assert len(p1.cells) > 0
    assert len(p1.nets) > 0

    # Path 200 check
    p200 = report.paths[-1]
    assert p200.id == 200
    assert p200.slack == 0.0917
    assert p200.status == "MET"

    # Histogram check
    assert len(report.histogram_bins) > 0
    total_in_bins = sum(b.count for b in report.histogram_bins)
    assert total_in_bins == 200

    # Filtering check
    failing_filtered = report.filter_paths(only_failing=True)
    assert len(failing_filtered) == 5

